BEGIN;
ALTER TABLE restaurants ADD COLUMN IF NOT EXISTS address TEXT NOT NULL DEFAULT '';
ALTER TABLE restaurants ADD COLUMN IF NOT EXISTS promo_banner_image TEXT NOT NULL DEFAULT '';
ALTER TABLE restaurants ADD COLUMN IF NOT EXISTS promo_banner_title TEXT NOT NULL DEFAULT 'Ofertas especiais';
ALTER TABLE restaurants ADD COLUMN IF NOT EXISTS promo_banner_text TEXT NOT NULL DEFAULT 'Confira nossas promoções e aproveite';
ALTER TABLE restaurants ADD COLUMN IF NOT EXISTS promo_banner_active INTEGER NOT NULL DEFAULT 0;
ALTER TABLE restaurants ADD COLUMN IF NOT EXISTS latitude DOUBLE PRECISION;
ALTER TABLE restaurants ADD COLUMN IF NOT EXISTS longitude DOUBLE PRECISION;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS delivery_fee_cents INTEGER NOT NULL DEFAULT 0;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS delivery_zone_name TEXT NOT NULL DEFAULT '';
ALTER TABLE orders ADD COLUMN IF NOT EXISTS delivery_distance_km DOUBLE PRECISION;
CREATE TABLE IF NOT EXISTS product_promotions (id TEXT PRIMARY KEY,restaurant_id TEXT NOT NULL,product_id TEXT NOT NULL,discount_type TEXT NOT NULL CHECK(discount_type IN ('fixed','percent')),promotional_price_cents INTEGER,discount_percent INTEGER,weekdays_json TEXT NOT NULL DEFAULT '[1,2,3,4,5,6,7]',active INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(restaurant_id,product_id));
CREATE TABLE IF NOT EXISTS delivery_zones (id TEXT PRIMARY KEY,restaurant_id TEXT NOT NULL,name TEXT NOT NULL,fee_mode TEXT NOT NULL CHECK(fee_mode IN ('fixed','per_km')),fee_cents INTEGER NOT NULL DEFAULT 0,per_km_cents INTEGER NOT NULL DEFAULT 100,distance_km DOUBLE PRECISION NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(restaurant_id,name));
COMMIT;
